from fastapi import FastAPI, HTTPException, Response
from pydantic import BaseModel, Field
class NoteIn(BaseModel):
    text:str=Field(min_length=1)
def build_app():
    app=FastAPI()
    store={}
    next_id=1
    @app.post('/notes',status_code=201)
    async def create(note:NoteIn):
        nonlocal next_id
        item={'id':next_id,'text':note.text}
        store[next_id]=item
        next_id+=1
        return dict(item)
    @app.get('/notes/{key}')
    async def read(key:int):
        if key not in store: raise HTTPException(404,'not found')
        return dict(store[key])
    @app.delete('/notes/{key}',status_code=204)
    async def delete(key:int):
        if key not in store: raise HTTPException(404,'not found')
        del store[key]
        return Response(status_code=204)
    return app
